steps.script:
# Isolate the Custodian Guard mid-board and park the Boyz in engagement
# range (~0.5" edge-to-edge; 32mm bases are ~25.2px in radius at 40px/inch).
var g = GameState.state["units"]["U_CUSTODIAN_GUARD_A"]
for i in range(g["models"].size()):
	g["models"][i]["position"] = {"x": 300.0 + float(i) * 36.0, "y": 1200.0}
var b = GameState.state["units"]["U_BOYZ_K"]
for i in range(b["models"].size()):
	b["models"][i]["position"] = {"x": 300.0 + float(i) * 36.0, "y": 1270.0}
	b["models"][i]["wounds"] = 99
	b["models"][i]["current_wounds"] = 99
return true

# The rule really is live for the isolated squad...
var snap = PhaseManager.get_current_phase_instance().game_state_snapshot
return FactionAbilityManager.check_against_all_odds(snap["units"]["U_CUSTODIAN_GUARD_A"], snap)

# ...and NOT for a control squad still standing among its friends.
var snap = PhaseManager.get_current_phase_instance().game_state_snapshot
return FactionAbilityManager.check_against_all_odds(snap["units"]["U_CUSTODIAN_GUARD_B"], snap)

# The board tracker (which drives the sparkle) must agree with the engine.
var st = FactionAbilityManager.get_against_all_odds_status("U_CUSTODIAN_GUARD_A")
return st.get("applicable", false) and st.get("active", false)

# Every model of the squad sparkles (the predicate TokenVisual._draw reads).
var layer = tree.root.get_node("Main").get_node("BoardRoot/TokenLayer")
var sparkling = 0
for child in layer.get_children():
	var n = child
	if not n.has_meta("unit_id") and n.get_child_count() > 0:
		n = n.get_child(0)
	if not n.has_meta("unit_id"):
		continue
	if str(n.get_meta("unit_id")) != "U_CUSTODIAN_GUARD_A":
		continue
	if n.has_method("_has_against_all_odds") and n._has_against_all_odds():
		sparkling += 1
return sparkling

# A crowded friendly squad must NOT sparkle — the marker has to mean something.
var layer = tree.root.get_node("Main").get_node("BoardRoot/TokenLayer")
for child in layer.get_children():
	var n = child
	if not n.has_meta("unit_id") and n.get_child_count() > 0:
		n = n.get_child(0)
	if not n.has_meta("unit_id"):
		continue
	if str(n.get_meta("unit_id")) != "U_CUSTODIAN_GUARD_B":
		continue
	if n.has_method("_has_against_all_odds") and n._has_against_all_odds():
		return "crowded squad is sparkling"
return true

# The card must say what the bonus IS, not merely name it.
var t = tree.root.get_node("Main")._token_hover_label.get_parsed_text()
return t.contains("+1 to Hit") and t.contains("+1 to Wound")

# THE FIX, hit stage: the dock names the rule behind the modified threshold.
var d = tree.root.get_node("Main").get_node("FightController").fight_resolution_dock
var txt = ""
for row in d.modifier_box.get_children():
	txt += row.text + "|"
return d.modifier_header.visible and txt.contains("Against All Odds: +1 to hit")

# The status line now also states WHAT is being rolled against.
var d = tree.root.get_node("Main").get_node("FightController").fight_resolution_dock
return d.status_label.text.contains("hit roll") and d.status_label.text.contains("+")

# THE FIX, wound stage: this is the '2+ to wound' the report was about.
var d = tree.root.get_node("Main").get_node("FightController").fight_resolution_dock
var txt = ""
for row in d.modifier_box.get_children():
	txt += row.text + "|"
return d.modifier_header.visible and txt.contains("Against All Odds: +1 to wound")

# ...and the reason travels with it, not just the number.
var d = tree.root.get_node("Main").get_node("FightController").fight_resolution_dock
var txt = ""
for row in d.modifier_box.get_children():
	txt += row.text + "|"
return txt.contains("within 6")

# The Dice Log names the source too — no more anonymous 'Wound modifier: +1'.
var log = tree.root.get_node("Main").get_node("FightController").dice_log_display
return log.get_parsed_text().contains("Against All Odds")

var panel = tree.root.get_node("Main").get_node_or_null("HUD_Left/GameLogPanel")
if panel == null:
	for n in tree.root.get_node("Main").find_children("*", "", true, false):
		if n.has_method("get_dice_log_display") or n.get("_tab_dice_button") != null:
			panel = n
			break
if panel == null:
	return "panel not found"
panel._tab_dice_button.emit_signal("pressed")
return true
